// Starred routes, kept in this browser's localStorage (per origin: http://localhost:8787 and :8000 are separate).
// Each entry: { id, name, created, parts (route points, pins as p[2] = 1), settings, optIdx, stats, coords ([lon, lat, z]) }.
// Storage can be missing or full (private windows, quota): every call is guarded and reports failure to the caller.
const KEY = 'cyclescape.saved.v1';

export function listSaved() {
  try { const v = JSON.parse(localStorage.getItem(KEY) ?? '[]'); return Array.isArray(v) ? v : []; } catch { return []; }
}
function write(list) {
  try { localStorage.setItem(KEY, JSON.stringify(list)); return true; } catch (e) { console.warn('saved routes: storage failed', e); return false; }
}
// newest first; returns the entry, or null when storage is unavailable or full
export function addSaved(entry) {
  const e = { id: `r${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`, created: new Date().toISOString(), ...entry };
  return write([e, ...listSaved()]) ? e : null;
}
export function removeSaved(id) { return write(listSaved().filter((e) => e.id !== id)); }
export function renameSaved(id, name) { return write(listSaved().map((e) => (e.id === id ? { ...e, name } : e))); }
export const getSaved = (id) => listSaved().find((e) => e.id === id) ?? null;
