// Flyover: a low chase camera that follows a route over MapLibre's 3D terrain, like a bird flying behind the rider.
// The camera sits `back` metres behind the rider and `height` metres above the (rendered, exaggerated) ground, looking
// at a point `ahead` metres in front of the rider; MapLibre's calculateCameraOptionsFromTo turns that into
// center / zoom / pitch / bearing. The heading is the direction of travel over a ±`window` metre stretch, smoothed in
// time, so switchbacks don't swing the camera.
//
// track: routeTrack(coords, zAt) — positions are metres along the route polyline (t in [0, L]).
// createFlyover(map, { onMove(t, lngLat), onChange({ active, playing, speed }), terrain: { source, exaggeration } })
//   .start(track, t0)  saves the view, turns 3D terrain on, starts playing from t0
//   .play() .pause() .toggle()  .setPos(t) (pauses; used when scrubbing the elevation profile)
//   .cycleSpeed()  .exit() restores the view and the terrain setting
export const FLY = { back: 520, ahead: 160, height: 190, window: 300, speeds: [500, 1000, 2000], turnRate: 2.2 };

const R2D = 180 / Math.PI;
// planar helpers around a latitude (metres)
const kxAt = (lat) => Math.cos(lat / R2D) * 111320, KY = 110574;
export function offset([lon, lat], bearingDeg, dist) {
  const b = bearingDeg / R2D;
  return [lon + (Math.sin(b) * dist) / kxAt(lat), lat + (Math.cos(b) * dist) / KY];
}

// coords: [[lon, lat], ...]; zAt(t): route elevation in metres at distance t (optional)
export function routeTrack(coords, zAt = () => 0) {
  const cs = coords, cum = [0];
  for (let k = 1; k < cs.length; k++) { const kx = kxAt(cs[k][1]); cum.push(cum[k - 1] + Math.hypot((cs[k][0] - cs[k - 1][0]) * kx, (cs[k][1] - cs[k - 1][1]) * KY)); }
  const L = cum[cum.length - 1];
  const at = (t) => {
    const d = Math.max(0, Math.min(L, t));
    let lo = 1, hi = cum.length - 1; // first index with cum >= d
    while (lo < hi) { const m = (lo + hi) >> 1; if (cum[m] < d) lo = m + 1; else hi = m; }
    const j = lo, f = cum[j] > cum[j - 1] ? (d - cum[j - 1]) / (cum[j] - cum[j - 1]) : 0;
    return [cs[j - 1][0] + f * (cs[j][0] - cs[j - 1][0]), cs[j - 1][1] + f * (cs[j][1] - cs[j - 1][1])];
  };
  // direction of travel at t: from the point w behind to the point w ahead (clamped at the ends)
  const heading = (t, w = FLY.window) => {
    const a = at(Math.max(0, Math.min(t, L - 1) - w)), b = at(Math.min(L, Math.max(t, 1) + w));
    return Math.atan2((b[0] - a[0]) * kxAt(a[1]), (b[1] - a[1]) * KY) * R2D;
  };
  return { coords: cs, cum, L, at, heading, zAt };
}

const wrap180 = (a) => ((((a + 180) % 360) + 360) % 360) - 180;

export function createFlyover(map, { onMove = () => {}, onChange = () => {}, terrain = null } = {}) {
  let track = null, t = 0, playing = false, speedIdx = 0, bearing = 0, raf = 0, last = 0, saved = null, addedTerrain = false;
  const exag = () => map.getTerrain()?.exaggeration ?? 1;
  // rendered ground height (exaggerated) at a point; falls back to the route's own elevation while DEM tiles load
  const ground = (ll, zRoute) => {
    let h = 0;
    try { h = map.terrain ? map.terrain.getElevationForLngLatZoom(new maplibregl.LngLat(ll[0], ll[1]), map.transform.tileZoom) : 0; } catch { h = 0; }
    return Math.max(h || 0, (zRoute || 0) * exag());
  };
  const state = () => ({ active: !!track, playing, speed: speedIdx, t, L: track?.L ?? 0 });
  function place(dt) {
    const rider = track.at(t), want = track.heading(t);
    bearing = dt == null ? want : bearing + wrap180(want - bearing) * Math.min(1, dt * FLY.turnRate);
    const cam = offset(rider, bearing + 180, FLY.back), target = offset(rider, bearing, FLY.ahead);
    const zr = track.zAt(t), zc = track.zAt(Math.max(0, t - FLY.back));
    const altTarget = ground(target, zr), altCam = Math.max(ground(cam, zc), altTarget) + FLY.height;
    const opts = map.calculateCameraOptionsFromTo(new maplibregl.LngLat(cam[0], cam[1]), altCam, new maplibregl.LngLat(target[0], target[1]), altTarget);
    map.jumpTo(opts);
    onMove(t, rider);
  }
  function frame(now) {
    raf = 0;
    if (!track || !playing) return;
    const dt = last ? Math.min(0.5, (now - last) / 1000) : 0; last = now; // slow devices keep real speed (choppier), up to 2 fps
    t = Math.min(track.L, t + FLY.speeds[speedIdx] * dt);
    place(dt);
    if (t >= track.L) { pause(); return; }
    raf = requestAnimationFrame(frame);
  }
  function play() {
    if (!track) return;
    if (t >= track.L) t = 0;
    playing = true; last = 0;
    if (!raf) raf = requestAnimationFrame(frame);
    onChange(state());
  }
  function pause() { playing = false; if (raf) cancelAnimationFrame(raf); raf = 0; onChange(state()); }
  function start(tr, t0 = 0) {
    if (!tr || tr.L < 50) return;
    if (!track) {
      saved = { center: map.getCenter(), zoom: map.getZoom(), bearing: map.getBearing(), pitch: map.getPitch() };
      if (!map.getTerrain() && terrain && map.getSource(terrain.source)) { map.setTerrain(terrain); addedTerrain = true; }
    }
    track = tr; t = Math.max(0, Math.min(tr.L, t0));
    place(null);
    play();
  }
  function setPos(nt) { if (!track) return; if (playing) pause(); t = Math.max(0, Math.min(track.L, nt)); place(null); onChange(state()); }
  function exit() {
    if (!track) return;
    pause(); track = null;
    if (addedTerrain) { map.setTerrain(null); addedTerrain = false; }
    if (saved) map.easeTo({ ...saved, duration: 600 });
    saved = null;
    onChange(state());
  }
  // a user drag / zoom / rotate pauses the flight (programmatic jumpTo events carry no originalEvent)
  map.on('movestart', (e) => { if (playing && e.originalEvent) pause(); });
  // HTML markers are placed with the terrain height known at the time; once tiles finish loading, place the rider again
  map.on('idle', () => { if (track && !playing) onMove(t, track.at(t)); });
  return { start, play, pause, toggle: () => (playing ? pause() : play()), setPos, exit,
    cycleSpeed: () => { speedIdx = (speedIdx + 1) % FLY.speeds.length; onChange(state()); return speedIdx; },
    get active() { return !!track; }, get playing() { return playing; }, get t() { return t; }, get track() { return track; }, state };
}
