// Per-metre resistance multipliers for road atoms (1 = a flat, quiet local road).
//
//   multiplier = traffic(V, trucks) × tunnel/snowshed × unpaved × climbing(grade) × Strava       (motor roads)
//              = base[class]        × tunnel/snowshed × unpaved × climbing(grade) × Strava       (paths, tracks)
//
// Traffic (research-traffic.md §4): V = estimated vehicles/day per atom (graph atomTraffic, web/src/traffic.mjs),
// H = large-vehicle share. traffic = clamp(((V · (1 + 2H)) / 1000)^τ, 1, cap): roads at or below 1,000 veh/day count
// as quiet (1), and τ is the rider's traffic aversion (0.3 tolerant · 0.5 avoid · 0.7 strongly avoid). At τ = 0.5,
// 4,000/day ≈ ×2.2, 12,000 ≈ ×3.8, 25,000 ≈ ×5.5. Width is inside V, so the old 'narrow' factor only applies to
// graphs without traffic estimates, which fall back to the class weights `base`.
//
// Climbing model (rider profile):
//
//   climb(g) = min(cap, 1 + α·g/2 + (max(0, g − g0) / s)²)          g = |grade|, e.g. 0.06
//
//   • energy term  α·g/2 — α is "flat metres a rider would ride to avoid climbing 1 m" (the UI shows it as the
//     detour in km you'd accept to skip 100 m of climbing: α = 10 ⇔ 1 km). The road graph is undirected, so a road
//     is climbed in one of its two directions only: the expected climb per metre is g/2.
//   • intensity term — a quadratic penalty above a comfortable grade g0 with scale s. Long gentle climbs pay mostly
//     the (linear) energy term; short steep pitches of the same total height pay far more, because the penalty grows
//     with the square of the excess grade, not with the height gained.
//
// Why not a hard "I'm fine with N metres of climbing per trip" budget? In a circuit (and in any shortest-path /
// flow model with fixed edge weights) every edge's cost must be independent of the route that uses it. A budget is
// a route-level, non-additive constraint: the 400th metre of climbing would be free and the 600th unacceptable,
// depending on what came before. That needs path state (resource-constrained routing), which a linear
// electrical network cannot hold. α is the per-metre *price* such a budget trades against: a rider with a large
// budget is one for whom climbing is cheap (small α); a low-budget rider has a large α. The intensity term then
// keeps steepness, not just total height, in the picture.
//
// The "Avoid climbs" preset approximates the raster model's slope factor 1 + (g/0.04)² (2%→1.25, 4%→2, 6%→3.25,
// 8%→5, 10%→7.25): here 2%→1.18, 4%→1.93, 6%→3.34, 8%→5.4, 10%→8.1.

export const PROFILES = {
  avoid: { label: 'Avoid climbs', climb: { alpha: 10, g0: 0.01, s: 0.035, cap: 15 } },
  steady: { label: 'Steady climber', climb: { alpha: 5, g0: 0.05, s: 0.03, cap: 15 } },
  strong: { label: 'Strong climber', climb: { alpha: 2, g0: 0.07, s: 0.04, cap: 15 } },
};

export const TRAFFIC_PRESETS = {
  tolerant: { label: "Don't mind traffic", tau: 0.3 },
  avoid: { label: 'Avoid traffic', tau: 0.5 },
  strong: { label: 'Strongly avoid traffic', tau: 0.7 },
};

export const DEFAULTS = {
  // common road classes (web/CONTRACT.md §1)
  base: { 1: 4.0, 2: 2.5, 4: 1.8, 6: 1.3, 8: 1.0, 9: 1.0, 10: 1.3, 11: 0.8, 12: 2.0, 13: 1.2 },
  narrow: 0.9,                                              // roadwidth_c >= 3 (< 5.5 m) on non-national roads
  tunnel: [[100, 2], [500, 4], [1000, 6], [Infinity, 8]],   // tunnel run length (m) -> multiplier
  avoidTunnels: true,     // user preference: never ride through tunnels unless there is no other way
  walkways: true, walkwayOn: 1.3, walkwayOff: 3, // UI 'Walkways and narrow lanes' (narrow lanes, 徒歩道, 庭園路)
  tunnelAvoidFactor: 50,
  snowshed: 1.5,
  unpaved: 1.0,           // no penalty by default (user preference: unpaved is fine, more fun if anything); < 1 favours it
  strava: 0.8,                                              // where Strava shows rides
  stravaMinPct: 50,
  climb: { ...PROFILES.avoid.climb },
  descent: { g0: 0.06, s: 0.05 }, // steep descents: 8% -> x1.16, 10% -> x1.64, 15% -> x4.2 (braking, not energy)
  traffic: { tau: 0.5, v0: 1000, cap: 8, heavyWeight: 2 },  // see the header; tau = traffic aversion
  // bike facility along a road (graph atomBike):
  //   2 separated track / parallel bike path: the road costs `separated` (a multiplier like a road type; default
  //     = the cycleway base x0.8), whatever the traffic beside it, so it is slightly preferred over quiet streets
  //   1 painted lane: the traffic factor shrinks toward 1, ft' = 1 + (ft - 1) * lane (you still ride in traffic)
  //   3 shared sidewalk/path alongside (bikes with pedestrians, e.g. 自転車歩行者道): fixed `shared`, worse than a quiet street
  bike: { lane: 0.5, separated: 0.8, shared: 1.5 }, // user: bike paths should carry no (or very low) penalty
  // personal taste per road class (UI: Advanced > Road type preferences), x0.5 prefer .. x3 avoid; default 1
  typePref: {},
};

// decoded vehicles/day from the graph's u8 code (graph-io atomTraffic); 0 = no estimate
export const trafficV = (code) => (code ? 10 ** ((code + 40) / 40) : 0);

export function trafficFactor(V, truckPct, P = DEFAULTS) {
  const T = P.traffic ?? DEFAULTS.traffic;
  return Math.min(T.cap, Math.max(1, ((V * (1 + (T.heavyWeight * (truckPct || 8)) / 100)) / T.v0) ** T.tau));
}

// Direction-aware climbing. Uphill pays the full energy term (α per metre climbed) plus the intensity term;
// downhill pays only a braking/discomfort term on steep descents (above P.descent.g0, scale P.descent.s).
// The best route (directed search) uses climbUp / climbDown per direction of travel; the circuit model is
// undirected, so it uses their average: climbFactor(g) = (up + down) / 2.
export function climbUp(g, P = DEFAULTS) {
  const { alpha, g0, s, cap } = P.climb ?? DEFAULTS.climb;
  const ex = Math.max(0, g - g0) / s;
  return Math.min(cap, 1 + alpha * g + ex * ex);
}
export function climbDown(g, P = DEFAULTS) {
  const { g0, s } = P.descent ?? DEFAULTS.descent;
  const ex = Math.max(0, g - g0) / s;
  return Math.min((P.climb ?? DEFAULTS.climb).cap, 1 + ex * ex);
}
export function climbFactor(g, P = DEFAULTS) {
  return (climbUp(g, P) + climbDown(g, P)) / 2;
}

// Same formula from plain fields (for scripts that work on road pieces rather than the typed graph).
// V / truckPct: estimated vehicles/day and large-vehicle %; without V (old graphs) the class weights apply.
// dir: +1 travelling uphill, -1 downhill, 0 undirected (circuit model)
// bike: 0 none, 1 painted lane, 2 dedicated cycleway alongside, 3 shared sidewalk/path alongside (graph atomBike)
export function multiplier(rc, rw, grade, tunnelRun, flags, stravaPct, P = DEFAULTS, V = 0, truckPct = 0, dir = 0, bike = 0) {
  let f;
  if (V > 0 && rc <= 9) f = trafficFactor(V, truckPct, P);
  else { f = P.base[rc] ?? 1; if (rw >= 3 && rc !== 1) f *= P.narrow; }
  const B = P.bike ?? DEFAULTS.bike;
  if (bike === 2 && rc <= 9) f = B.separated; // dedicated cycleway alongside: you ride it like a cycleway, whatever the traffic
  else if (bike === 3 && rc <= 9) f = B.shared ?? 1.5; // shared sidewalk (自転車歩行者道): out of traffic but slow (pedestrians, driveways)
  else {
    if (bike === 1 && rc <= 9 && f > 1) f = 1 + (f - 1) * B.lane; // painted lane: part of the traffic penalty remains
    f *= P.typePref?.[rc] ?? 1; // road-type taste applies to riding on the road itself
    // walkways and narrow lanes (GSI < 3 m lanes 9, 徒歩道 12, 庭園路 13): GSI cannot tell bollards, steps or
    // no-bike paths, so they cost a little more when allowed (footpaths keep their own x2) and a lot when not
    if (rc === 9 || rc === 12 || rc === 13) f *= P.walkways === false ? (P.walkwayOff ?? 3) : rc === 12 ? 1 : (P.walkwayOn ?? 1.3);
  }
  // avoidTunnels: a prohibitive factor so the flow (current map) goes around tunnels too; the best route closes them outright
  if (flags & 1) f *= P.avoidTunnels ? (P.tunnelAvoidFactor ?? 50) : P.tunnel.find(([lim]) => tunnelRun < lim)[1];
  else if (flags & 4) f *= P.snowshed;
  if (flags & 8) f *= P.unpaved;
  f *= dir > 0 ? climbUp(grade, P) : dir < 0 ? climbDown(grade, P) : climbFactor(grade, P);
  if (stravaPct >= P.stravaMinPct) f *= P.strava;
  return f;
}

// Typed graph (web/CONTRACT.md §2): atom i.
export function atomMultiplier(graph, i, P = DEFAULTS, dir = 0) {
  return multiplier(graph.atomRc[i], graph.atomRw[i], graph.atomGrade[i] / 1e4, graph.atomTunnelRun[i],
    graph.atomFlags[i], graph.atomStrava[i], P,
    graph.atomTraffic ? trafficV(graph.atomTraffic[i]) : 0, graph.atomTruck ? graph.atomTruck[i] : 0, dir,
    graph.atomBike ? graph.atomBike[i] : 0);
}
// Atom i travelled along its chain's direction (forward) or against it: +1 uphill / -1 downhill from its elevations
// (0 = unknown -> undirected average). A rise under 0.5 m over the atom counts as flat.
export function atomDirection(graph, i, forward) {
  if (!graph.atomZ0 || !graph.atomZ1) return 0;
  const rise = (graph.atomZ1[i] - graph.atomZ0[i]) * (forward ? 1 : -1);
  return rise > 0.5 ? 1 : rise < -0.5 ? -1 : 0;
}

export function describe(P = DEFAULTS) {
  const c = P.climb ?? DEFAULTS.climb;
  return `detour ${(c.alpha / 10).toFixed(1)} km per 100 m climbed · comfortable ≤ ${(100 * c.g0).toFixed(1)}% · steep scale ${(100 * c.s).toFixed(1)}%`;
}
